:root{--ink:#1d1f23;--muted:#5b616b;--line:#c9ced6;--head:#eef0f3;--bg:#ffffff;
--g:#1e7b34;--gbg:#e3f3e6;--b:#1f5fae;--bbg:#e2ecf8;--v:#6b3fa0;--vbg:#efe6f8;--y:#7a5a00;--ybg:#fff3c4;--o:#4d535c;--obg:#e7e9ec;--r:#b42318;--rbg:#fde7e5}
*{box-sizing:border-box}
html,body{margin:0;background:var(--bg);color:var(--ink)}
body{font:13px/1.45 system-ui,-apple-system,"Segoe UI",Roboto,Arial,sans-serif;padding:16px 20px 40px;max-width:1500px;margin:0 auto}
body::before{content:"REKONSTRUKTION";position:fixed;top:45%;left:50%;transform:translate(-50%,-50%) rotate(-28deg);font-size:120px;font-weight:800;letter-spacing:.08em;color:rgba(180,35,24,.06);pointer-events:none;z-index:0;white-space:nowrap}
main{position:relative;z-index:1}
.pfoot{display:none}
.banner{border:3px solid var(--r);background:var(--rbg);color:#7a1209;padding:12px 16px;font-weight:700;font-size:16px;margin-bottom:14px}
h1{font-size:22px;margin:6px 0 4px}
h2{font-size:17px;margin:28px 0 8px;padding-bottom:4px;border-bottom:2px solid var(--ink);break-after:avoid}
h3{font-size:14px;margin:18px 0 6px;break-after:avoid}
p{margin:6px 0}
.meta{color:var(--muted);margin-bottom:10px}
.tw{overflow-x:auto;margin:6px 0 10px}
table{border-collapse:collapse;width:100%;font-size:11.5px}
caption{text-align:left;font-weight:600;padding:2px 0}
th,td{border:1px solid var(--line);padding:3px 5px;vertical-align:top;text-align:left}
th{background:var(--head);font-weight:600}
tr{break-inside:avoid}
thead{display:table-header-group}
td.n,th.n{text-align:right;white-space:nowrap}
.s{display:inline-block;font-style:normal;font-weight:700;font-size:10px;letter-spacing:.03em;padding:1px 5px;border-radius:3px;border:1px solid;margin:1px 2px 1px 0;white-space:nowrap}
.g{color:var(--g);background:var(--gbg);border-color:var(--g)}
.b{color:var(--b);background:var(--bbg);border-color:var(--b)}
.v{color:var(--v);background:var(--vbg);border-color:var(--v)}
.y{color:var(--y);background:var(--ybg);border-color:#b08a00}
.o{color:var(--o);background:var(--obg);border-color:var(--o)}
.r{color:var(--r);background:var(--rbg);border-color:var(--r)}
.box{border:1px solid var(--line);border-left:5px solid var(--o);padding:8px 12px;margin:10px 0;background:#fafbfc}
.box.red{border-left-color:var(--r)}
small,.sm{font-size:10.5px;color:var(--muted)}
tr.wid td{background:#fff6f5}
tr.mod td{background:#faf7fd}
tr.bel td{background:#f3faf4}
tr.sum td{font-weight:700;background:var(--head)}
.sig{display:grid;grid-template-columns:1fr 1fr;gap:40px;margin-top:30px}
.sig div{border-top:1px solid var(--ink);padding-top:4px;min-height:70px}
input[type=checkbox]{width:14px;height:14px;margin:0}
ul,ol{margin:4px 0 8px 20px;padding:0}li{margin:2px 0}
@media (max-width:700px){body{padding:12px 16px}.sig{grid-template-columns:1fr}body::before{font-size:60px}}
@page{size:A4 landscape;margin:11mm 10mm 14mm}
@media print{
 body{padding:0;max-width:none;font-size:10px}
 table{font-size:8.6px}
 th,td{padding:2px 3px}
 .tw{overflow:visible}
 .pb{break-before:page}
 *{-webkit-print-color-adjust:exact;print-color-adjust:exact}
 body::before{position:fixed;font-size:130px;color:rgba(180,35,24,.07)}
 .pfoot{display:block;position:fixed;bottom:-9mm;left:0;right:0;font-size:8px;color:#7a1209;text-align:center}
}

